static void plan_reconstruct(const VersionPlan& vp, int i, int j, int c, std::vector<Layout>& out) {
    const PlanDec& d = vp.pick(i, j, c);
    Layout n; n.lo = i; n.span = j - i; n.mode = d.mode; n.cached = d.cached;
    size_t self = out.size();
    out.push_back(n);
    int kids = (int)d.cs.size();
    for (int z = 0; z < kids; ++z) plan_reconstruct(vp, d.cs[z], d.ce[z], d.buds[z], out);
    for (int z = 0; z < kids; ++z) out[self].children.push_back((int)(self + 1 + z));
}

